package com.careflow.hospital.reservations;
import jakarta.validation.Valid;import java.util.*;import org.springframework.http.*;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/reservations") @PreAuthorize("hasRole('PATIENT')") public class ReservationController {private final ReservationService service;public ReservationController(ReservationService service){this.service=service;}@PostMapping ResponseEntity<ReservationDtos.View> create(Authentication auth,@Valid@RequestBody ReservationDtos.Create request){return ResponseEntity.status(HttpStatus.CREATED).body(service.create(user(auth),request));}@GetMapping List<ReservationDtos.View> list(Authentication auth){return service.list(user(auth));}@DeleteMapping("/{id}")@ResponseStatus(HttpStatus.NO_CONTENT)void cancel(Authentication auth,@PathVariable UUID id){service.cancel(user(auth),id);}private UUID user(Authentication auth){return UUID.fromString(auth.getName());}}
